import{_ as t,o,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Proposals — Sales-Side Project Modeling (Architecture & Build Plan)","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/proposals.md","filePath":"decisions/proposals.md"}'),n={name:"decisions/proposals.md"};function s(d,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="proposals-—-sales-side-project-modeling-architecture-build-plan" tabindex="-1">Proposals — Sales-Side Project Modeling (Architecture &amp; Build Plan) <a class="header-anchor" href="#proposals-—-sales-side-project-modeling-architecture-build-plan" aria-label="Permalink to &quot;Proposals — Sales-Side Project Modeling (Architecture &amp; Build Plan)&quot;">​</a></h1><p><strong>Status:</strong> Planning (2026-06-27). Owner-approved direction; chunked for incremental delivery (the proven George→Lenny cadence — spec each phase when the prior lands). <strong>Purpose:</strong> Let an agency owner scaffold and price a <em>prospective</em> engagement during a sales conversation — using the agency&#39;s real cost data, people, disciplines, and target margin — <strong>without polluting operational data and without surfacing anything to the team until the deal is won</strong>. This is the &quot;see around the corner&quot; surface clients keep asking for.</p><hr><h2 id="_1-the-problem-why-this-exists" tabindex="-1">1. The problem (why this exists) <a class="header-anchor" href="#_1-the-problem-why-this-exists" aria-label="Permalink to &quot;1. The problem (why this exists)&quot;">​</a></h2><p>Owners told us, repeatedly, that they want to use VERA <em>during the sale</em>. When a prospect gets specific, the owner wants to shape the engagement the same way they&#39;d run a real one:</p><blockquote><p>&quot;Our price is <strong>$100,000</strong>. We&#39;ve kept the <strong>5:1 ratio</strong> intact by projecting <strong>$20k of people cost</strong> — two designers for six weeks, a strategist part-time, a vendor for the build.&quot;</p></blockquote><p>VERA already knows everything needed to answer that <em>honestly</em>: real cost rates, the agency blended rate, each person&#39;s discipline, the target Labor Efficiency Ratio, the committed-cost and Forecasted-P&amp;L math (shipped #1559). The owner wants to point that engine at a deal that <strong>does not exist yet</strong>.</p><p>The trap is contamination. A prospective engagement must not:</p><ul><li><strong>leak into the operational numbers</strong> — utilization, capacity, availability, &quot;team of N&quot; denominators, dashboards, reminders, the morning briefing, P&amp;L. A project that may never sell cannot move any real figure.</li><li><strong>signal anything to the team</strong> — nobody gets an envelope, a DM, a morning-briefing line, or an audit-channel post for speculative work. The people being modeled must not know a proposal exists until (and unless) it converts.</li></ul><h3 id="what-this-is-not" tabindex="-1">What this is <strong>not</strong> <a class="header-anchor" href="#what-this-is-not" aria-label="Permalink to &quot;What this is **not**&quot;">​</a></h3><p><strong>Proposals is not a CRM.</strong> No contacts, no pipeline stages, no email tracking, no activity log, no deal-flow reporting. It is a <em>project modeler</em> for a named prospect — the shape and price of one possible engagement — and nothing more. If a feature request smells like CRM, it belongs in a different product.</p><hr><h2 id="_2-the-two-hard-invariants-load-bearing" tabindex="-1">2. The two hard invariants (load-bearing) <a class="header-anchor" href="#_2-the-two-hard-invariants-load-bearing" aria-label="Permalink to &quot;2. The two hard invariants (load-bearing)&quot;">​</a></h2><p>Everything below is in service of these two. They are non-negotiable and every phase must preserve them.</p><ol><li><p><strong>No operational pollution.</strong> Proposals live in their own data domain (<code>proposals</code>, and later <code>proposal_roles</code>) that <strong>no operational query reads</strong>. Isolation is <em>structural</em>, not a filter: there is nothing to exclude because nothing joins to it. <code>readProjects</code>, <code>readBudgets</code>, <code>readTimeEntries</code>, the dashboard CTEs, the forecast queries, capacity, reminders — none of them reference the proposals tables, so a proposal <strong>cannot</strong> appear in any aggregate by construction.</p></li><li><p><strong>No user-facing signal until conversion.</strong> Proposals are <strong>owner/admin-only</strong>. The endpoints are <strong>console-only</strong> (defined in <code>mcp-server.js</code>, called via <code>callEndpoint</code>, <strong>absent from <code>MCP_TOOLS</code></strong>), so they are unreachable from Slack — Claude has no tool for them and a user could never trigger one. No DMs, no morning-briefing lines, <strong>and no audit-channel post at all</strong> — not even a dollar-free one, because the audit channel is team-visible and the prospect&#39;s existence must stay private until conversion. A team member learns of the work <strong>only</strong> when a proposal is Won and explicitly converted into a real <code>planned</code> project (Phase 2).</p></li></ol><h3 id="reading-real-data-is-allowed-writing-back-is-not" tabindex="-1">Reading real data is allowed; writing back is not <a class="header-anchor" href="#reading-real-data-is-allowed-writing-back-is-not" aria-label="Permalink to &quot;Reading real data is allowed; writing back is not&quot;">​</a></h3><p>The owner explicitly wants realistic modeling, so the builder <strong>may read</strong> real user data — discipline, current cost rate, availability — to populate and price the model. This is <strong>one-directional</strong>: proposals read from <code>users</code> / <code>rate_history</code> / availability, and write <strong>only</strong> to the proposals domain. Nothing in the proposals flow writes to <code>users</code>, <code>budgets</code>, <code>projects</code>, <code>time_entries</code>, or any operational table (until an explicit Phase-2 conversion, which is a deliberate, owner-initiated, audited act).</p><hr><h2 id="_3-the-decision-a-separate-in-app-data-domain" tabindex="-1">3. The decision: a separate <strong>in-app data domain</strong> <a class="header-anchor" href="#_3-the-decision-a-separate-in-app-data-domain" aria-label="Permalink to &quot;3. The decision: a separate **in-app data domain**&quot;">​</a></h2><p>Broaden VERA with a new, self-contained data domain — <code>proposals</code> (Phase 0) and <code>proposal_roles</code> (Phase 1) — that reuses VERA&#39;s existing financial engine and lives behind the same auth, RLS, and console the owner already uses. Isolation is <em>free</em> because no operational query references the new tables.</p><h3 id="why-this-shape" tabindex="-1">Why this shape <a class="header-anchor" href="#why-this-shape" aria-label="Permalink to &quot;Why this shape&quot;">​</a></h3><ul><li><strong>Reuse, don&#39;t reinvent the crown jewels.</strong> Pricing a proposal is exactly the Forecasted-P&amp;L question already solved on the project detail page (#1559): revenue vs. fully-committed people cost, with LER and a target-ratio check. We reuse the <em>same</em> primitives — <code>TARGET_LER</code>, <code>getAgencyBlendedCostRate()</code>, &quot;people budget = contract ÷ target LER&quot;, the revenue/cost/LER/profit panel grammar. No second financial engine to keep in sync.</li><li><strong>Inherit the platform.</strong> Same OAuth/session, same per-tenant RLS (<code>requestContext.run</code>), same owner-gating idiom (<code>isOwnerLevel</code>), same server-rendered console. A new owner-only page slots in beside Reports / Forecast / Portfolio.</li><li><strong>The Won handoff is an in-process status flip</strong>, not a cross-system integration (Phase 2).</li></ul><h3 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Alternative</th><th>Why rejected</th></tr></thead><tbody><tr><td><strong>Ghost users</strong> (one shadow <code>users</code> row per real person, the owner&#39;s first instinct)</td><td><strong>Inverts the safety model.</strong> You&#39;d create real <code>users</code>/<code>budgets</code> rows, then try to <em>exclude</em> them from every aggregate — utilization, capacity denominators, the morning briefing, reminders, dashboard, forecast. Every existing and future aggregate becomes a place you must remember to filter; <strong>one missed filter leaks a phantom project to the team.</strong> It also fights identity invariants (Slack-ID validation, display-name auto-sync, <code>isDeliveryResource</code>). Pollution-by-default with exclusion bolted on is exactly backwards from isolation-by-construction.</td></tr><tr><td><strong>A separate companion app</strong> that talks to VERA</td><td>Must <strong>re-implement or re-read the crown-jewel math</strong> (LER, blended rate, committed cost) behind a <em>second</em> RLS/auth/deploy boundary, plus data sync, plus turning the Won→handoff into a brittle cross-system integration. All of the cost of a new system, none of the benefit over an in-app domain that already has the data and the math in-process.</td></tr></tbody></table><hr><h2 id="_4-data-model" tabindex="-1">4. Data model <a class="header-anchor" href="#_4-data-model" aria-label="Permalink to &quot;4. Data model&quot;">​</a></h2><h3 id="proposals-phase-0" tabindex="-1"><code>proposals</code> (Phase 0) <a class="header-anchor" href="#proposals-phase-0" aria-label="Permalink to &quot;`proposals` (Phase 0)&quot;">​</a></h3><p>One row = one possible engagement for one named prospect.</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>tenant_id</code></td><td><code>uuid</code></td><td>PK part; RLS GUC</td></tr><tr><td><code>id</code></td><td><code>integer</code></td><td>PK part; app-assigned <code>MAX(id)+1</code> per tenant (matches <code>disciplines</code>/<code>liabilities</code>)</td></tr><tr><td><code>name</code></td><td><code>text NOT NULL</code></td><td>Working title, e.g. &quot;Acme Q3 Rebrand&quot;</td></tr><tr><td><code>prospect_name</code></td><td><code>text</code></td><td>Free-text prospect label — <strong>deliberately not a <code>clients</code> FK</strong> (no CRM, no <code>clients</code> pollution). Nullable.</td></tr><tr><td><code>project_type</code></td><td><code>text NOT NULL DEFAULT &#39;Fixed Price&#39;</code></td><td><code>CHECK IN (&#39;T&amp;M&#39;,&#39;Fixed Price&#39;,&#39;Pro Bono&#39;,&#39;Internal&#39;)</code> — the four creatable types, so a Won proposal maps cleanly to <code>create_project</code> in Phase 2</td></tr><tr><td><code>contract_value</code></td><td><code>numeric(12,2)</code></td><td>The price being proposed. Nullable while drafting.</td></tr><tr><td><code>target_ler</code></td><td><code>numeric(6,2)</code></td><td>Per-proposal target ratio override. Nullable → costing uses the code <code>TARGET_LER</code> (5). Lets an owner model a different ratio for one deal without touching the global constant.</td></tr><tr><td><code>status</code></td><td><code>text NOT NULL DEFAULT &#39;draft&#39;</code></td><td><code>CHECK IN (&#39;draft&#39;,&#39;won&#39;,&#39;lost&#39;,&#39;converted&#39;)</code>. Phase 0 uses <code>draft</code>; <code>won</code>/<code>lost</code>/<code>converted</code> anchor Phase 2.</td></tr><tr><td><code>notes</code></td><td><code>text</code></td><td>Freeform. Nullable.</td></tr><tr><td><code>created_by</code></td><td><code>text NOT NULL</code></td><td>Slack ID of the owner (matches <code>liabilities.created_by</code>).</td></tr><tr><td><code>created_at</code></td><td><code>timestamptz NOT NULL DEFAULT now()</code></td><td>List sorts newest-first by <code>id</code>.</td></tr><tr><td><code>converted_project_id</code></td><td><code>integer</code></td><td>Nullable soft reference to <code>projects.id</code> (no hard FK) — set once at Phase-2 conversion; NULL otherwise.</td></tr></tbody></table><p>RLS: <code>ENABLE</code> + <code>FORCE ROW LEVEL SECURITY</code> + the standard <code>tenant_isolation</code> policy (<code>tenant_id = current_setting(&#39;app.tenant_id&#39;, true)::uuid</code>), <code>GRANT SELECT, INSERT, UPDATE, DELETE … TO vera_app</code>. No sequence grant (app-assigned integer id).</p><h3 id="proposal-roles-phase-1-—-shipped-1566" tabindex="-1"><code>proposal_roles</code> (Phase 1 — shipped #1566) <a class="header-anchor" href="#proposal-roles-phase-1-—-shipped-1566" aria-label="Permalink to &quot;`proposal_roles` (Phase 1 — shipped #1566)&quot;">​</a></h3><p>One row = one staffing line on a proposal.</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>tenant_id</code></td><td><code>uuid</code></td><td>PK part; composite FK to <code>proposals</code></td></tr><tr><td><code>id</code></td><td><code>integer</code></td><td>PK part; app-assigned <code>MAX(id)+1</code> per tenant</td></tr><tr><td><code>proposal_id</code></td><td><code>integer NOT NULL</code></td><td>Composite FK → <code>proposals(tenant_id, id)</code> ON DELETE CASCADE</td></tr><tr><td><code>discipline_id</code></td><td><code>integer</code></td><td>Nullable; maps to <code>disciplines.id</code> — not a hard FK so archived disciplines survive</td></tr><tr><td><code>user_id</code></td><td><code>integer</code></td><td>Nullable; &quot;model as this specific person&quot;; overrides discipline for costing</td></tr><tr><td><code>planned_hours</code></td><td><code>numeric(10,2) NOT NULL DEFAULT 0</code></td><td>Hours for this line</td></tr><tr><td><code>billing_rate</code></td><td><code>numeric(10,2)</code></td><td>Nullable; used only for T&amp;M revenue per line</td></tr><tr><td><code>task</code></td><td><code>text</code></td><td>Optional label (e.g. &quot;Design&quot;, &quot;Strategy&quot;)</td></tr><tr><td><code>created_at</code></td><td><code>timestamptz NOT NULL DEFAULT now()</code></td><td></td></tr></tbody></table><p><strong>Cost-rate precedence per line:</strong></p><ol><li><strong>Specific person</strong> (<code>user_id != null</code>) → that person&#39;s current cost rate from <code>rate_history</code> (latest <code>effective_from ≤ today</code>, id-tiebreak). Person with no rate row → <code>$0.00/hr</code>, <code>rate_source: &#39;person&#39;</code> (visible and intentional).</li><li><strong>Discipline-blended</strong> (<code>discipline_id != null</code>, no user) → mean of current cost rates of active delivery resources in that discipline (rates &gt; 0 only). Discipline with no rated resources → falls through to agency.</li><li><strong>Agency-blended</strong> (neither, or discipline with no rates) → <code>getAgencyBlendedCostRate()</code> (trailing-90d delivery-resource weighted mean).</li></ol><p><strong>Revenue rule:</strong></p><ul><li>T&amp;M → Σ(<code>planned_hours</code> × <code>billing_rate</code>) per line (requires billing_rate set per line).</li><li>Fixed Price / Pro Bono / Internal → <code>contract_value</code> (Pro Bono/Internal have null/0 → $0 revenue).</li></ul><p><strong>People budget</strong> = revenue ÷ (<code>target_ler</code> ?? <code>TARGET_LER</code>). LER = revenue ÷ cost. Margin = (profit / revenue) × 100.</p><p><strong>Implementation:</strong> <code>lib/proposal-costing.js</code> — <code>computeProposalPnl(proposal, roles)</code> (pure, unit-tested) + <code>resolveRoleRates(roles)</code> (DB-backed, calls <code>getAgencyBlendedCostRate()</code> <strong>before</strong> entering <code>withTenant</code> to avoid nested transaction). One-directional import: <code>proposal-costing</code> imports <code>forecast</code>; <code>forecast</code> never imports <code>proposal-costing</code> — the structural guard that keeps operational reads unable to reach proposal data.</p><p>RLS, PK, grant: same pattern as <code>proposals</code> (migration <code>0028</code>).</p><hr><h2 id="_5-phasing-roadmap-each-row-one-future-lenny-issue" tabindex="-1">5. Phasing roadmap (each row = one future Lenny issue) <a class="header-anchor" href="#_5-phasing-roadmap-each-row-one-future-lenny-issue" aria-label="Permalink to &quot;5. Phasing roadmap (each row = one future Lenny issue)&quot;">​</a></h2><p>Vertical slices; spec each when the prior lands. <strong>Do not open them all at once.</strong></p><table tabindex="0"><thead><tr><th>Phase</th><th>Deliverable</th><th>Proves / de-risks</th><th>Depends on</th></tr></thead><tbody><tr><td><strong>P0 — Data domain + console shell</strong> ✅ <strong>shipped #1563</strong></td><td><code>proposals</code> migration (+ RLS), DAL readers/writers, <strong>console-only</strong> owner-gated MCP endpoints (<code>create_proposal</code> / <code>list_proposals</code> / <code>update_proposal</code> / <code>delete_proposal</code>), and <code>/console/proposals</code> — list + create/edit/delete the proposal shell (name, prospect, type, contract value, target LER, status, notes). <strong>No staffing, no costing yet.</strong></td><td>The whole new domain end-to-end <strong>and both invariants</strong>: a brand-new tenant-scoped table with RLS; owner-only gating; a console page; Slack-unreachability (endpoints absent from <code>MCP_TOOLS</code>); structural operational invisibility. Highest-leverage de-risk — keep it a shell.</td><td>Console v1</td></tr><tr><td><strong>P1 — Staffing + live costing</strong> ✅ <strong>shipped #1566</strong></td><td><code>proposal_roles</code> migration + DAL + role endpoints; a proposal <strong>detail</strong> page with a staffing table (add/edit/remove role lines: discipline + optional specific person + hours) and a live <strong>Proposed P&amp;L</strong> card reusing the Forecasted-P&amp;L grammar (revenue vs people cost, LER, target-ratio check, profit/loss spill). Reads real cost rates / blended rate; writes only to <code>proposal_roles</code>.</td><td>The crown-jewel math re-pointed at proposals — the actual &quot;$100k, 5:1 intact&quot; answer.</td><td>P0</td></tr><tr><td><strong>P2 — Won → convert</strong> ✅ <strong>shipped #1568</strong></td><td>Mark a proposal <code>won</code>; a <strong>Convert</strong> action creates a real, active project via <code>create_project</code>, flips the proposal to <code>converted</code> (recording <code>converted_project_id</code>), best-effort-enables the staffing-line tasks, and shows an envelope-assignment checklist. The <strong>first</strong> audited moment — one dollar-free audit post.</td><td>The deliberate, owner-initiated boundary crossing from speculative to real.</td><td>P1</td></tr><tr><td><strong>P3 — Capacity simulation (opt-in, read-only)</strong></td><td>An <strong>opt-in</strong> overlay that shows what a proposal&#39;s staffing <em>would</em> do to capacity/availability if it landed — read-only, never written, never shown to the modeled people.</td><td>&quot;Can we even staff this?&quot; during the sale, without committing anything.</td><td>P1</td></tr></tbody></table><p><strong>P0, P1, and P2 have shipped.</strong> P3 (opt-in capacity simulation) is the remaining deferred follow-up, specced when it&#39;s next.</p><hr><hr><h2 id="_7-conversion-phase-2-—-shipped-1568" tabindex="-1">7. Conversion (Phase 2 — shipped #1568) <a class="header-anchor" href="#_7-conversion-phase-2-—-shipped-1568" aria-label="Permalink to &quot;7. Conversion (Phase 2 — shipped #1568)&quot;">​</a></h2><p>Conversion is the one place a proposal touches operational data, and it is deliberate, owner-initiated, and audited.</p><p><strong>Flow.</strong> <code>won</code> proposal → owner clicks <strong>Convert to project</strong> on <code>/console/proposals/:id</code> → confirm form (project name, client [defaults to the prospect], deadline, hours budget [defaults to Σ staffing-line hours], contract value for Fixed Price, optional billing rate for T&amp;M) → <code>POST /console/proposals/:id/convert</code>.</p><p><strong>Orchestration (console route, no new MCP endpoint).</strong> The route composes existing endpoints via <code>callEndpoint</code>: <code>get_proposal_costing</code> (load proposal + roles) → <code>create_project</code> (real, <strong>active</strong> project; client auto-created from the prospect via <code>findOrCreateClient</code>) → best-effort <code>enable_task_for_project</code> for each distinct staffing-line task → <code>update_proposal</code> (status <code>converted</code> + <code>converted_project_id</code>). Because it is orchestrated in the console and adds no MCP tool, proposals remain unreachable from Slack.</p><p><strong>Audit.</strong> Exactly one <code>postConsoleAudit</code> message — <em>the first audited moment in a proposal&#39;s life</em>. Per Rule 21 it carries no dollar figures (the project&#39;s contract value is never named in the audit).</p><p><strong>Guards.</strong> Only a <code>won</code> proposal converts, and never twice. <code>create_project</code> runs first (the irreversible act); if it fails — including a duplicate project name (returned as <code>success:false</code>) — the proposal stays <code>won</code> and nothing is flipped.</p><p><strong>After conversion.</strong> Status is <code>converted</code>; <code>converted_project_id</code> links to the project. The detail page shows a <strong>staffing checklist</strong> (each modelled role → person/discipline, hours, task, and what to do) plus a link into the project to create the envelopes. Envelopes are <strong>not</strong> auto-created — the checklist is guidance; the owner assigns them with the project&#39;s existing Add-envelope flow.</p><hr><h2 id="_6-what-this-does-not-change" tabindex="-1">6. What this does <strong>not</strong> change <a class="header-anchor" href="#_6-what-this-does-not-change" aria-label="Permalink to &quot;6. What this does **not** change&quot;">​</a></h2><ul><li><strong>Operational tables and queries</strong> — <code>users</code>, <code>projects</code>, <code>budgets</code>, <code>time_entries</code>, dashboards, forecast, capacity, reminders, the morning/evening briefing — all untouched. A proposal cannot move any of them.</li><li><strong>The RLS / tenant-isolation contract</strong> — the new tables use the identical pattern; no change to how isolation works.</li><li><strong>The Slack surface</strong> — proposals are console-only; Slack stays exactly the <code>user</code>-role surface. Claude gets no proposals tool.</li><li><strong>Financial isolation</strong> — proposals are owner/admin-only; managers and users never see them. The existing endpoint-as-security-boundary model is reused, not re-implemented.</li><li><strong>The financial engine</strong> — <code>TARGET_LER</code>, <code>getAgencyBlendedCostRate()</code>, committed-cost and Forecasted-P&amp;L math are <em>reused</em>, not forked.</li></ul>',57)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
